  const vv=Math.min(v,206),a=Math.PI*(1-vv/200);s+=NZ_L(x,y,(x+(R-26)*Math.cos(a)).toFixed(1),(y-(R-26)*Math.sin(a)).toFixed(1),col,7)+`<circle cx="${x}" cy="${y}" r="11" fill="${col}"/>`;
